// are generated by scripts/generate-tram-models.mjs.
//
// sections[].openModelKey ('<modelKey>-open') is the doors-OPEN GLB variant
// (right-side passenger doors slid aside, warm interior glow) rendered while a
// tram dwells at a stop. Sections without passenger doors (14t-a driver-door
// cab, 52t-b/d pantograph middles) have no open variant.

