/**
 * Wrap the metro asset require so the module also loads under jest, where
 * `.glb` is not in the transformer allowlist (metro resolves these statically
 * at bundle time, so a missing file still fails the app build).
 */
function glbAsset(load: () => number): number {
  try {
    return load();
  } catch {
    return 0;
  }
}

/** modelKey → bundled GLB asset id, for `Asset.fromModule` + <Models>. */
